d7a90000-0000-4000-8000-000000000001	d7a80000-0000-4000-8000-000000000001	1	2	RIVER_TIDE	1	{"audio": [{"cue": "ENTER", "stepId": "estuary", "volume": 0.9, "assetRef": "voice"}], "river": {"stakes": [{"x": 0.40, "id": "stake-1", "length": 0.22}, {"x": 0.45, "id": "stake-2", "length": 0.19}, {"x": 0.50, "id": "stake-3", "length": 0.24}, {"x": 0.55, "id": "stake-4", "length": 0.17}, {"x": 0.60, "id": "stake-5", "length": 0.21}, {"x": 0.43, "id": "stake-6", "length": 0.16}, {"x": 0.57, "id": "stake-7", "length": 0.23}, {"x": 0.52, "id": "stake-8", "length": 0.18}]}, "steps": [{"id": "estuary", "hint": "Bản đồ minh họa vùng cửa sông hiện ra rồi mờ dần — camera giữ góc nhìn tổng quan.", "title": "Cửa sông Bạch Đằng", "easing": "easeInOut", "narration": "Cửa sông Bạch Đằng nối ra biển Đông — địa thế triều mạnh, luồng nông, nhiều bãi bồi. Đây là nơi Ngô Quyền chọn làm trận địa đón quân Nam Hán.", "durationMs": 1200, "targetState": {"obstructed": false, "waterLevel": 0.55, "boatProgress": 0.0}}, {"id": "stake-prep", "hint": "Camera hạ xuống mặt nước, các cọc lần lượt lộ ở vùng bãi.", "title": "Đóng cọc ngầm", "easing": "easeInOut", "narration": "Trước trận, quân ta đóng sẵn bãi cọc gỗ lim bịt sắt dưới lòng sông. Sử liệu không ghi bố trí chính xác — sơ đồ chỉ minh họa ý tưởng trận địa.", "durationMs": 1200, "targetState": {"obstructed": false, "waterLevel": 0.30, "boatProgress": 0.0, "highlightStakes": true}}, {"id": "tide-rise", "hint": "Kéo mực nước lên để tự thấy cọc chìm hẳn.", "title": "Triều lên", "easing": "easeInOut", "narration": "Nước triều dâng cao, che khuất đỉnh cọc. Từ trên thuyền nhìn xuống khó nhận ra chướng ngại vật ẩn phía dưới.", "durationMs": 1200, "targetState": {"obstructed": false, "waterLevel": 0.90, "boatProgress": 0.0}, "allowedInteractions": ["WATER_LEVEL_CONTROL"]}, {"id": "decoy", "hint": "Camera bám theo thuyền dụ — thuyền địch tiến từ mép phải vào trung tâm bãi.", "title": "Dụ địch vào bãi", "easing": "easeInOut", "narration": "Lúc nước lớn, thuyền dụ dẫn hạm đội Nam Hán tiến vào vùng bãi cọc. Đoàn địch theo sau, không biết đáy sông đã bố trận.", "durationMs": 1200, "targetState": {"obstructed": false, "waterLevel": 0.90, "boatProgress": 0.72, "decoyProgress": 1}}, {"id": "prediction", "hint": "Dừng lại và dự đoán trước khi xem nước rút.", "title": "Điểm quyết định", "easing": "easeInOut", "narration": "Triều sắp rút. Nếu thuyền địch đã vào sâu bãi cọc, điều gì sẽ xảy ra khi mực nước hạ? Đây là lúc cả trận địa chuyển pha.", "durationMs": 1400, "targetState": {"obstructed": false, "waterLevel": 0.85, "boatProgress": 0.72, "decoyProgress": 1}, "allowedInteractions": ["PREDICTION"]}, {"id": "tide-fall", "hint": "Camera zoom vào bãi + gợn nước đánh dấu điểm mấu chốt.", "title": "Triều rút — cọc lộ", "easing": "easeInOut", "narration": "Triều rút nhanh, đỉnh cọc nhô lên khỏi mặt sông. Thuyền địch mắc vào bãi, không thể quay đầu hay tiếp tục tiến.", "durationMs": 1200, "targetState": {"obstructed": false, "waterLevel": 0.26, "boatProgress": 0.85, "decoyProgress": 1, "highlightStakes": true}, "allowedInteractions": ["WATER_LEVEL_CONTROL"]}, {"id": "counterattack", "hint": "Glow quanh thuyền dụ đánh dấu điểm dồn lực — thuyền địch mắc kẹt.", "title": "Phản công phối hợp", "easing": "easeInOut", "narration": "Khi thuyền địch vướng cọc, quân ta phản công đồng loạt từ nhiều hướng. Thời điểm triều hạ chính là thời điểm quyết định trận đánh.", "durationMs": 1200, "targetState": {"obstructed": true, "waterLevel": 0.26, "boatProgress": 0.85, "decoyProgress": 1, "counterattackProgress": 1}}, {"id": "evidence", "hint": "Fade out — chuỗi quyết định khép lại bằng chứng cứ.", "title": "Kết luận có chứng cứ", "easing": "easeInOut", "narration": "Chiến thắng Bạch Đằng là kết quả của chuỗi chủ động: chọn địa thế triều → chuẩn bị trận địa → dụ địch đúng lúc nước lớn → phản công đúng lúc nước rút. Đây là kết luận dựa trên bối cảnh, không phải chi tiết từng cọc hay từng thuyền được ghi lại.", "durationMs": 1400, "targetState": {"obs